import React, { useEffect, useState } from 'react'
import styled from 'styled-components'
import { useGlobalContext } from '../../context/globalContext';
import { InnerLayout } from '../../styles/Layouts';
import { dollar, trendingUp, calendar, piggy, book, users, bitcoin, card, yt, medical, food, takeaway, clothing, freelance, tv, calender, comment, trash } from '../../utils/Icons';
import Chart from '../Chart/Chart';

function Dashboard() {
    const { totalExpenses, incomes, expenses, totalIncome, totalBalance, getIncomes, getExpenses, getBudgetSuggestions } = useGlobalContext()
    const [suggestions, setSuggestions] = useState([])
    const [recentTransactions, setRecentTransactions] = useState([])
    const [isDarkMode, setIsDarkMode] = useState(false)

    useEffect(() => {
        getIncomes()
        getExpenses()
        fetchSuggestions()
        loadRecentTransactions()
    }, [])

    const fetchSuggestions = async () => {
        const sugg = await getBudgetSuggestions()
        setSuggestions(sugg)
    }

    const loadRecentTransactions = () => {
        const combined = [
            ...incomes.map(income => ({ ...income, type: 'income' })),
            ...expenses.map(expense => ({ ...expense, type: 'expense' }))
        ];
        combined.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));
        setRecentTransactions(combined.slice(0, 5));
    }

    const getGreeting = () => {
        const hour = new Date().getHours();
        if (hour < 12) return "Good morning";
        if (hour < 18) return "Good afternoon";
        return "Good evening";
    }

    const getCategoryIcon = (category) => {
        const icons = {
            salary: dollar, freelancing: freelance, investments: trendingUp, stocks: users,
            bitcoin: bitcoin, bank: card, youtube: yt, education: book, groceries: food,
            health: medical, subscriptions: tv, takeaways: takeaway, clothing: clothing,
            travelling: freelance, other: piggy
        };
        return icons[category] || piggy;
    }

    const toggleDarkMode = () => {
        setIsDarkMode(!isDarkMode);
        document.body.classList.toggle('dark-mode');
    }

    return (
        <DashboardStyled isDark={isDarkMode}>
            <InnerLayout>
                {/* Header Section */}
                <div className="dashboard-header">
                    <div className="greeting-section">
                        <h1>{getGreeting()}, Chandra 👋</h1>
                        <p>Here's your financial summary</p>
                    </div>
                    <div className="header-controls">
                        <button className="theme-toggle" onClick={toggleDarkMode}>
                            {isDarkMode ? '☀️' : '🌙'}
                        </button>
                    </div>
                </div>

                {/* Summary Cards */}
                <div className="summary-cards">
                    <div className="summary-card income-card">
                        <div className="card-icon">💰</div>
                        <div className="card-content">
                            <h3>Total Income</h3>
                            <p className="amount">${totalIncome().toLocaleString()}</p>
                            <span className="trend positive">+12% from last month</span>
                        </div>
                    </div>
                    <div className="summary-card expense-card">
                        <div className="card-icon">💸</div>
                        <div className="card-content">
                            <h3>Total Expenses</h3>
                            <p className="amount">${totalExpenses().toLocaleString()}</p>
                            <span className="trend negative">-8% from last month</span>
                        </div>
                    </div>
                    <div className="summary-card balance-card">
                        <div className="card-icon">⚖️</div>
                        <div className="card-content">
                            <h3>Net Balance</h3>
                            <p className={`amount ${totalBalance() >= 0 ? 'positive' : 'negative'}`}>
                                ${Math.abs(totalBalance()).toLocaleString()}
                            </p>
                            <span className="trend neutral">Current balance</span>
                        </div>
                    </div>
                </div>

                {/* Main Content Grid */}
                <div className="dashboard-grid">
                    {/* Charts Section */}
                    <div className="charts-section">
                        <div className="chart-header">
                            <h2>Spending Analytics</h2>
                            <select className="time-selector">
                                <option>Last 30 days</option>
                                <option>Last 3 months</option>
                                <option>Last 6 months</option>
                            </select>
                        </div>
                        <div className="chart-container">
                            <Chart />
                        </div>
                    </div>

                    {/* Recent Transactions */}
                    <div className="transactions-section">
                        <div className="section-header">
                            <h2>Recent Transactions</h2>
                            <button className="view-all-btn">View All</button>
                        </div>
                        <div className="transactions-list">
                            {recentTransactions.map((transaction) => (
                                <div key={transaction._id} className="transaction-item">
                                    <div className="transaction-icon">
                                        {getCategoryIcon(transaction.category)}
                                    </div>
                                    <div className="transaction-details">
                                        <h4>{transaction.title}</h4>
                                        <p>{transaction.category} • {new Date(transaction.createdAt).toLocaleDateString()}</p>
                                    </div>
                                    <div className={`transaction-amount ${transaction.type}`}>
                                        {transaction.type === 'income' ? '+' : '-'}${transaction.amount}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>

                    {/* AI Insights Panel */}
                    <div className="insights-section">
                        <div className="section-header">
                            <h2>💡 AI Insights</h2>
                        </div>
                        <div className="insights-content">
                            {suggestions.length > 0 ? (
                                <div className="insights-list">
                                    {suggestions.slice(0, 3).map((sugg, index) => (
                                        <div key={index} className="insight-card">
                                            <div className="insight-icon">🎯</div>
                                            <div className="insight-content">
                                                <h4>{sugg.category} Budget</h4>
                                                <p>{sugg.suggestion}</p>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            ) : (
                                <div className="empty-insights">
                                    <p>Add some transactions to get personalized AI insights!</p>
                                </div>
                            )}
                            <button className="ask-ai-btn">🤖 Ask AI Assistant</button>
                        </div>
                    </div>

                    {/* Budget Goals */}
                    <div className="goals-section">
                        <div className="section-header">
                            <h2>🎯 Budget Goals</h2>
                        </div>
                        <div className="goals-content">
                            <div className="goal-item">
                                <div className="goal-info">
                                    <h4>Emergency Fund</h4>
                                    <p>$2,500 / $5,000</p>
                                </div>
                                <div className="goal-progress">
                                    <div className="progress-bar">
                                        <div className="progress-fill" style={{width: '50%'}}></div>
                                    </div>
                                    <span>50%</span>
                                </div>
                            </div>
                            <div className="goal-item">
                                <div className="goal-info">
                                    <h4>Vacation Fund</h4>
                                    <p>$1,200 / $3,000</p>
                                </div>
                                <div className="goal-progress">
                                    <div className="progress-bar">
                                        <div className="progress-fill" style={{width: '40%'}}></div>
                                    </div>
                                    <span>40%</span>
                                </div>
                            </div>
                            <button className="add-goal-btn">+ Add New Goal</button>
                        </div>
                    </div>
                </div>
            </InnerLayout>
        </DashboardStyled>
    )
}

const DashboardStyled = styled.div`
    h1 {
        color: #2c3e50;
        font-size: 2.5rem;
        font-weight: 700;
        margin-bottom: 2rem;
        text-align: center;
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        -webkit-background-clip: text;
        -webkit-text-fill-color: transparent;
        background-clip: text;
    }

    .stats-con{
        display: grid;
        grid-template-columns: repeat(5, 1fr);
        gap: 2rem;

        .chart-con{
            grid-column: 1 / 4;
            height: 400px;
            background: linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%);
            border-radius: 20px;
            padding: 2rem;
            box-shadow: 0 20px 40px rgba(0,0,0,0.1);
            transition: transform 0.3s ease;

            &:hover {
                transform: translateY(-5px);
            }

            .amount-con{
                display: grid;
                grid-template-columns: repeat(4, 1fr);
                gap: 2rem;
                margin-top: 2rem;

                .income, .expense{
                    grid-column: span 2;
                }

                .income, .expense, .balance{
                    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                    color: white;
                    border-radius: 20px;
                    padding: 2rem;
                    box-shadow: 0 10px 30px rgba(102, 126, 234, 0.3);
                    transition: all 0.3s ease;
                    position: relative;
                    overflow: hidden;

                    &::before {
                        content: '';
                        position: absolute;
                        top: 0;
                        left: -100%;
                        width: 100%;
                        height: 100%;
                        background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
                        transition: left 0.5s;
                    }

                    &:hover::before {
                        left: 100%;
                    }

                    &:hover {
                        transform: translateY(-10px);
                        box-shadow: 0 20px 40px rgba(102, 126, 234, 0.4);
                    }

                    h2 {
                        font-size: 1.2rem;
                        margin-bottom: 1rem;
                        opacity: 0.9;
                    }

                    p{
                        font-size: 2.5rem;
                        font-weight: 700;
                        margin: 0;
                    }
                }

                .income {
                    background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
                }

                .expense {
                    background: linear-gradient(135deg, #fa709a 0%, #fee140 100%);
                }

                .balance{
                    grid-column: 2 / 4;
                    display: flex;
                    flex-direction: column;
                    justify-content: center;
                    align-items: center;
                    background: linear-gradient(135deg, #a8edea 0%, #fed6e3 100%);

                    p{
                        color: #2c3e50;
                        opacity: 1;
                        font-size: 3rem;
                        margin: 0;
                    }
                }
            }
        }

        .history-con{
            grid-column: 4 / -1;
            background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
            border-radius: 20px;
            padding: 2rem;
            box-shadow: 0 20px 40px rgba(0,0,0,0.1);
            color: white;

            h2{
                margin: 1rem 0;
                font-size: 1.5rem;
                font-weight: 600;
            }

            .salary-title{
                font-size: 1rem;
                margin-bottom: 1rem;
                span{
                    font-size: 1.5rem;
                    font-weight: 700;
                }
            }

            .salary-item{
                background: rgba(255, 255, 255, 0.2);
                backdrop-filter: blur(10px);
                border: 1px solid rgba(255, 255, 255, 0.3);
                padding: 1.5rem;
                border-radius: 15px;
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 1rem;
                transition: all 0.3s ease;

                &:hover {
                    background: rgba(255, 255, 255, 0.3);
                    transform: scale(1.02);
                }

                p{
                    font-weight: 600;
                    font-size: 1.4rem;
                    margin: 0;
                }
            }

            .suggestions{
                .suggestion-item{
                    background: rgba(255, 255, 255, 0.2);
                    backdrop-filter: blur(10px);
                    border: 1px solid rgba(255, 255, 255, 0.3);
                    padding: 1.5rem;
                    border-radius: 15px;
                    margin-bottom: 1rem;
                    transition: all 0.3s ease;

                    &:hover {
                        background: rgba(255, 255, 255, 0.3);
                        transform: scale(1.02);
                    }

                    p{
                        font-size: 1.2rem;
                        margin: 0;
                        line-height: 1.5;
                    }
                }
            }
        }
    }

    @media (max-width: 1200px) {
        .stats-con {
            grid-template-columns: 1fr;
            .chart-con {
                grid-column: 1;
            }
            .history-con {
                grid-column: 1;
            }
        }
    }
`;

export default Dashboard
